units = {  # 이름: (걸린 ms, 먼저 끝나야 하는 것들)
    "kernel": (900, []), "udev": (300, ["kernel"]), "mount-data": (450, ["udev"]),
    "network": (600, ["udev"]), "vehicle-msg": (250, ["network"]),
    "camera-svc": (400, ["udev"]), "hmi-app": (700, ["vehicle-msg", "mount-data"]),
}

def finish(u, memo):
    if u in memo:
        return memo[u]
    d, deps = units[u]
    memo[u] = d + max((finish(x, memo) for x in deps), default=0)
    return memo[u]

def chain(u, memo):
    deps = units[u][1]
    if not deps:
        return [u]
    return chain(max(deps, key=lambda x: finish(x, memo)), memo) + [u]

m = {}
print("before:", finish("hmi-app", m), "ms via", " > ".join(chain("hmi-app", m)))
units["hmi-app"] = (700, ["mount-data"])  # 메시지 서비스를 기다리지 않고 나중에 붙는다
m = {}
print("after: ", finish("hmi-app", m), "ms via", " > ".join(chain("hmi-app", m)))
# before: 2750 ms via kernel > udev > network > vehicle-msg > hmi-app
# after:  2350 ms via kernel > udev > mount-data > hmi-app

MAX_AGE_MS = 500
def handle(req, now_ms):
    age = now_ms - req["ts_ms"]
    return "RUN" if age <= MAX_AGE_MS else "DROP (age %dms)" % age
last = {"cmd": "fold_mirror", "ts_ms": 10_000}
for now in (10_120, 10_480, 11_900):
    print(now, handle(last, now))
# 10120 RUN
# 10480 RUN
